using namespace std;

void solve() {
    int n;
    cin >> n;
    vector<int> a(n), b(n);

    for(auto &it : a) cin >> it;
    for(auto &it : b) cin >> it;

    vector<bool> seen(n + 1);
    if(a.back() == b.back()) {
        cout << n << endl;
        return;
    }

    int ans = -1;
    for(int i = n - 2; i >= 0; i--) {
        if(a[i] == b[i] || a[i] == a[i + 1] || b[i] == b[i + 1] || seen[a[i]] || seen[b[i]]) {
            ans = i;
            break;
        }

        seen[a[i + 1]] = seen[b[i + 1]] = true;
    }

    cout << ans + 1 << endl;
}

int main() {
    int t;
    cin >> t;
    while(t--) solve();
}

#include <bits/stdc++.h>

using namespace std;

const int N = 2e5 + 10, MOD = 1e9 + 7;
#define int long long

vector<int> adj[N], lens;
int pw[N];
int lca;

void dfs(int u, int par, int len) {
    if(adj[u].size() > 2) lca = len;

    bool leaf = true;
    for(int v : adj[u]) {
        if(v != par) {
            dfs(v, u, len + 1);
            leaf = false;
        }
    }

    if(leaf) lens.push_back(len);
}

void solve() {
    int n;
    cin >> n;

    for(int i = 1; i <= n; i++) adj[i].clear();
    lens.clear();
    lca = -1;

    for(int i = 0; i < n - 1; i++) {
        int u, v;
        cin >> u >> v;
        adj[u].push_back(v);
        adj[v].push_back(u);
    }

    adj[1].push_back(0); // dummy node
    dfs(1, 0, 1);
    if(lens.size() > 2) cout << 0 << endl;
    else if(lens.size() == 1) cout << pw[n] << endl;
    else {
        int diff = abs(lens[0] - lens[1]);
        int x = diff + lca;
        if(diff) cout << (pw[x] + pw[x - 1]) % MOD << endl;
        else cout << (2 * pw[x]) % MOD << endl;
    }
}

signed main() {
    pw[0] = 1;
    for(int i = 1; i < N; i++) pw[i] = (pw[i - 1] * 2) % MOD;

    int t;
    cin >> t;
    while(t--) solve();
}

#include<bits/stdc++.h>
using namespace std;
typedef long long ll;
#define debug(x) cout << #x << " = " << x << "\n";
#define vdebug(a) cout << #a << " = "; for(auto x: a) cout << x << " "; cout << "\n";
mt19937 rng(chrono::steady_clock::now().time_since_epoch().count());
int uid(int a, int b) { return uniform_int_distribution<int>(a, b)(rng); }
ll uld(ll a, ll b) { return uniform_int_distribution<ll>(a, b)(rng); }

void solve(){
    int n, m;
    cin >> n >> m;

    vector<vector<array<int, 2>>> g(n);
    for (int i = 0; i < m; i++){
        int u, v, w;
        cin >> u >> v >> w;
        u--;
        v--;

        g[u].push_back({v, w});
        g[v].push_back({u, w});
    }

    auto uwu = [&](int u) -> vector<ll>{
        vector<ll> dis(n, 1e18);
        vector<bool> vis(n);       

        priority_queue<array<ll, 2>> q;
        q.push({0, u});
        while (q.size()){
            auto [d, c] = q.top();
            d = -d;
            q.pop();

            if (vis[c])
                continue;
            vis[c] = true;
            dis[c] = d;

            for (auto [x, w] : g[c]){
                if (vis[x])
                    continue;

                q.push({-max(d, 1LL * w), x});
            }
        }

        return dis;
    };

    ll ans = 1e18;
    vector<ll> dis_s = uwu(0), dis_t = uwu(n - 1);
    for (int u = 0; u < n; u++){
        for (auto [v, w] : g[u]){
            ans = min(ans, {max({dis_s[u], dis_t[v], 1LL * w}) + w});
        }
    }

    cout << ans << "\n";
}

int main(){
    ios::sync_with_stdio(false);
    cin.tie(0);

    int t;
    cin >> t;
    while (t--) solve();
}

#include <bits/stdc++.h>
using namespace std;
using ll = long long;
#define F first
#define S second
#define all(x) x.begin(), x.end()
#define pb push_back
#define FOR(i,a,b) for(int i = (a); i < (b); ++i)
#define trav(a,x) for(auto& a: x)
#define sz(x) (int)x.size()
template<typename T> istream& operator>>(istream& in, vector<T>& a) {for(auto &x : a) in >> x; return in;};

struct Node {
    int sum;    // total sum of segment
    int pref;   // max prefix sum
    int suff;   // max suffix sum
    int best;   // max subarray sum
    Node(): sum(0), pref(0), suff(0), best(0) {}
    Node(int x): sum(x), pref(max(0,x)), suff(max(0,x)), best(max(0,x)) {}
};

Node merge(const Node &L, const Node &R) {
    Node res;
    res.sum  = L.sum + R.sum;
    res.pref = max(L.pref, L.sum + R.pref);
    res.suff = max(R.suff, R.sum + L.suff);
    res.best = max({ L.best, R.best, L.suff + R.pref });
    return res;
}

struct segtree {
    int n;
    vector<Node> st;
     segtree(int _n) {
        n = _n;
        st.resize(4*n);
        build(1, 0, n-1);
    }
    void build(int p, int l, int r) {
        if (l == r) {
            st[p] = Node(-1);
            return;
        }
        int m = (l + r) / 2;
        build(p<<1,   l,   m);
        build(p<<1|1, m+1, r);
        st[p] = merge(st[p<<1], st[p<<1|1]);
    }
    void update(int p, int l, int r, int idx, int val) {
        if (l == r) {
            st[p] = Node(val);
            return;
        }
        int m = (l + r) / 2;
        if (idx <= m) update(p<<1,   l,   m, idx, val);
        else          update(p<<1|1, m+1, r, idx, val);
        st[p] = merge(st[p<<1], st[p<<1|1]);
    }
    void update(int idx, int val) {
        update(1, 0, n-1, idx, val);
    }
    Node query(int p, int l, int r, int i, int j) {
        if (i > r || j < l) {
            Node nullnode;
            nullnode.sum = 0;
            nullnode.pref = nullnode.suff = nullnode.best = INT_MIN;
            return nullnode;
        }
        if (l >= i && r <= j) {
            return st[p];
        }
        int m = (l + r) / 2;
        Node L = query(p<<1,   l,   m, i, j);
        Node R = query(p<<1|1, m+1, r, i, j);
        if (L.best == INT_MIN) return R;
        if (R.best == INT_MIN) return L;
        return merge(L, R);
    }
    int max_subarray() {
        Node res = query(1, 0, n-1, 0, n-1);
        return res.best;
    }
};

void solve() {
	int n, q; cin >> n >> q;
	vector<int> a(n); cin >> a;
	vector<vector<int>> at(n+1);
	FOR(i,0,n) at[a[i]].pb(i);
	vector<vector<array<int, 3>>> updates(n+1);
	FOR(idx,0,q){
		int i, x; cin >> i >> x;
		--i;
		if(x != a[i]){
			updates[a[i]].pb({idx, i, -1});
			a[i] = x;
			updates[x].pb({idx, i, 1});
		}
	}
	vector<vector<int>> final_at(n+1);
	FOR(i,0,n) final_at[a[i]].pb(i);
	segtree st(n);
	vector<int> init(n+1);
	vector<vector<pair<int,int>>> change(q);
	FOR(x,1,n+1){
		trav(i, at[x]){
			st.update(i, 1);
		}
		int cur = st.max_subarray();
		init[x] = cur;
		trav(i, updates[x]){
			st.update(i[1], i[2]);
			int new_cur = st.max_subarray();
			change[i[0]].pb({cur, new_cur});
			cur = new_cur;
		}
		trav(i, final_at[x]){
			st.update(i, -1);
		}
	}
	multiset<int> ms;
	FOR(i,1,n+1) ms.insert(init[i]);
	FOR(i,0,q){
		trav(j, change[i]){
			ms.erase(ms.find(j.F));
			ms.insert(j.S);
		}
		cout << *prev(ms.end())/2 << " ";
	}
	cout << "\n";
}

signed main() {
	cin.tie(0) -> sync_with_stdio(0);
	int t = 1;
	cin >> t;
	for(int test = 1; test <= t; test++){
		solve();
	}
}
